import React, { useState, useEffect } from 'react';
import axios from 'axios';

const DashboardOverview = () => {
  const [stats, setStats] = useState({
    totalProducts: 0,
    totalUsers: 0,
    totalOrders: 0,
    totalRevenue: 0,
    recentOrders: [],
    topProducts: []
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardStats();
  }, []);

  const fetchDashboardStats = async () => {
    try {
      // In a real app, you'd have a dedicated API endpoint for dashboard stats
      const [productsRes, usersRes, ordersRes] = await Promise.all([
        axios.get('/api/products?category=all'),
        axios.get('/api/users'),
        axios.get('/api/orders/admin/all')
      ]);

      const products = productsRes.data.products || [];
      const users = usersRes.data || [];
      const orders = ordersRes.orders || [];

      setStats({
        totalProducts: products.length,
        totalUsers: users.length,
        totalOrders: orders.length,
        totalRevenue: orders.reduce((sum, order) => sum + (order.totalAmount || order.totalPrice || 0), 0),
        recentOrders: orders.slice(0, 5),
        topProducts: products.slice(0, 5)
      });
      setLoading(false);
    } catch (error) {
      console.error('Failed to fetch dashboard stats:', error);
      // Set default values on error
      setStats({
        totalProducts: 0,
        totalUsers: 0,
        totalOrders: 0,
        totalRevenue: 0,
        recentOrders: [],
        topProducts: []
      });
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="loading">Loading dashboard...</div>;
  }

  return (
    <div className="dashboard-overview">
      <h2>Dashboard Overview</h2>
      
      {/* Stats Cards */}
      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon products">
            <i className="fas fa-box"></i>
          </div>
          <div className="stat-info">
            <h3>{stats.totalProducts}</h3>
            <p>Total Products</p>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon users">
            <i className="fas fa-users"></i>
          </div>
          <div className="stat-info">
            <h3>{stats.totalUsers}</h3>
            <p>Total Users</p>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon orders">
            <i className="fas fa-shopping-cart"></i>
          </div>
          <div className="stat-info">
            <h3>{stats.totalOrders}</h3>
            <p>Total Orders</p>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon revenue">
            <i className="fas fa-dollar-sign"></i>
          </div>
          <div className="stat-info">
            <h3>₹{stats.totalRevenue.toFixed(2)}</h3>
            <p>Total Revenue</p>
          </div>
        </div>
      </div>

      <div className="dashboard-content">
        {/* Recent Orders */}
        <div className="dashboard-section">
          <h3>Recent Orders</h3>
          <div className="recent-orders">
            {stats.recentOrders.length > 0 ? (
              <table>
                <thead>
                  <tr>
                    <th>Order ID</th>
                    <th>Customer</th>
                    <th>Date</th>
                    <th>Amount</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {stats.recentOrders.map((order) => (
                    <tr key={order._id}>
                      <td>#{order._id?.slice(-8)}</td>
                      <td>{order.user?.name || 'N/A'}</td>
                      <td>{new Date(order.createdAt).toLocaleDateString()}</td>
                      <td>${order.totalAmount || 0}</td>
                      <td>
                        <span className={`status-badge ${order.status || 'pending'}`}>
                          {order.status || 'Pending'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <p className="no-data">No recent orders</p>
            )}
          </div>
        </div>

        {/* Top Products */}
        <div className="dashboard-section">
          <h3>Top Products</h3>
          <div className="top-products">
            {stats.topProducts.length > 0 ? (
              <div className="product-list">
                {stats.topProducts.map((product) => (
                  <div key={product._id} className="product-item">
                    <div className="product-image">
                      {product.images && product.images.length > 0 ? (
                        <img src={product.images[0]} alt={product.name} />
                      ) : (
                        <div className="no-image">No Image</div>
                      )}
                    </div>
                    <div className="product-info">
                      <h4>{product.name}</h4>
                      <p className="price">₹{product.price}</p>
                      <p className="stock">Stock: {product.stock}</p>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <p className="no-data">No products available</p>
            )}
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="quick-actions">
        <h3>Quick Actions</h3>
        <div className="action-buttons">
          <button className="action-btn">
            <i className="fas fa-plus"></i>
            Add New Product
          </button>
          <button className="action-btn">
            <i className="fas fa-tags"></i>
            Manage Categories
          </button>
          <button className="action-btn">
            <i className="fas fa-percentage"></i>
            Create Promotion
          </button>
          <button className="action-btn">
            <i className="fas fa-chart-bar"></i>
            View Analytics
          </button>
        </div>
      </div>
    </div>
  );
};

export default DashboardOverview;
